describe('User Profile - Timezone Settings', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'TestPassword123!',
    username: 'testuser'
  };

  beforeEach(() => {
    cy.visit('/');
    cy.clearCookies();
    cy.clearLocalStorage();

    // Login
    cy.get('[data-testid="login-email"]').type(testUser.email);
    cy.get('[data-testid="login-password"]').type(testUser.password);
    cy.get('[data-testid="login-submit"]').click();
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Navigate to profile settings
    cy.get('[data-testid="user-menu-trigger"]').click();
    cy.get('[data-testid="profile-settings-link"]').click();
    cy.get('[data-testid="profile-settings-page"]').should('be.visible');
  });

  it('should successfully set timezone to a valid timezone option', () => {
    // Click on timezone dropdown
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-dropdown"]').should('have.attr', 'aria-expanded', 'true');

    // Select a specific timezone
    cy.get('[data-testid="timezone-option-america-newyork"]').click();
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'America/New_York');

    // Save settings
    cy.get('[data-testid="save-profile-settings"]').click();
    cy.get('[data-testid="success-notification"]').should('be.visible');
    cy.get('[data-testid="success-notification"]').should('contain', 'Settings saved successfully');

    // Verify timezone persists after page reload
    cy.reload();
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'America/New_York');
  });

  it('should handle timezone change from one timezone to another', () => {
    // Set initial timezone
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-option-europe-london"]').click();
    cy.get('[data-testid="save-profile-settings"]').click();
    cy.get('[data-testid="success-notification"]').should('be.visible');

    // Change to different timezone
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-option-asia-tokyo"]').click();
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'Asia/Tokyo');

    cy.get('[data-testid="save-profile-settings"]').click();
    cy.get('[data-testid="success-notification"]').should('be.visible');

    // Verify new timezone is saved
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'Asia/Tokyo');
  });

  it('should display all available timezone options in dropdown', () => {
    cy.get('[data-testid="timezone-dropdown"]').click();

    // Verify dropdown is open and contains timezone options
    cy.get('[data-testid="timezone-option-america-newyork"]').should('be.visible');
    cy.get('[data-testid="timezone-option-europe-london"]').should('be.visible');
    cy.get('[data-testid="timezone-option-asia-tokyo"]').should('be.visible');
    cy.get('[data-testid="timezone-option-australia-sydney"]').should('be.visible');
    cy.get('[data-testid="timezone-option-utc"]').should('be.visible');

    // Verify options are selectable
    cy.get('[data-testid="timezone-dropdown"] [role="option"]').should('have.length.greaterThan', 5);
  });

  it('should show error when timezone change fails', () => {
    // Intercept the save request and force an error
    cy.intercept('PATCH', '/api/user/profile/timezone', {
      statusCode: 500,
      body: { error: 'Failed to update timezone' }
    }).as('timezoneUpdateFailed');

    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-option-america-losangeles"]').click();
    cy.get('[data-testid="save-profile-settings"]').click();

    cy.wait('@timezoneUpdateFailed');
    cy.get('[data-testid="error-notification"]').should('be.visible');
    cy.get('[data-testid="error-notification"]').should('contain', 'Failed to update timezone');
  });

  it('should require timezone selection before saving', () => {
    // Clear current timezone if set
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-clear-option"]').click();

    // Attempt to save without timezone
    cy.get('[data-testid="save-profile-settings"]').click();

    // Verify validation error appears
    cy.get('[data-testid="timezone-error-message"]').should('be.visible');
    cy.get('[data-testid="timezone-error-message"]').should('contain', 'Timezone is required');
  });

  it('should filter timezone options when searching', () => {
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-search-input"]').type('America');

    // Verify only America timezones are shown
    cy.get('[data-testid="timezone-option-america-newyork"]').should('be.visible');
    cy.get('[data-testid="timezone-option-america-losangeles"]').should('be.visible');
    cy.get('[data-testid="timezone-option-america-chicago"]').should('be.visible');

    // Verify non-matching timezones are hidden
    cy.get('[data-testid="timezone-option-asia-tokyo"]').should('not.be.visible');
    cy.get('[data-testid="timezone-option-europe-london"]').should('not.be.visible');
  });

  it('should maintain timezone setting across multiple profile updates', () => {
    // Set timezone
    cy.get('[data-testid="timezone-dropdown"]').click();
    cy.get('[data-testid="timezone-option-europe-paris"]').click();
    cy.get('[data-testid="save-profile-settings"]').click();
    cy.get('[data-testid="success-notification"]').should('be.visible');

    // Update another profile field
    cy.get('[data-testid="profile-bio-input"]').clear().type('Updated bio');
    cy.get('[data-testid="save-profile-settings"]').click();
    cy.get('[data-testid="success-notification"]').should('be.visible');

    // Verify timezone is still set
    cy.get('[data-testid="timezone-dropdown"]').should('contain', 'Europe/Paris');
  });
});
